function normalizedMod(a, m) {
  if (typeof a !== "bigint" || typeof m !== "bigint")
    throw new TypeError("Use BigInt integers");
  if (m <= 0n) throw new RangeError("Use a positive modulus");
  return ((a % m) + m) % m;
}

function inverseMod(a, m) {
  if (typeof a !== "bigint" || typeof m !== "bigint")
    throw new TypeError("Use BigInt integers");
  if (m <= 1n) throw new RangeError("Use a modulus greater than 1");
  const { g, s } = extendedGcd(a, m);
  return g === 1n ? normalizedMod(s, m) : null;
}

function solveLinear(a, b, m) {
  if ([a, b, m].some(x => typeof x !== "bigint"))
    throw new TypeError("Use BigInt integers");
  if (m <= 0n) throw new RangeError("Use a positive modulus");
  const { g, s } = extendedGcd(a, m);
  if (b % g !== 0n) return null;
  const period = m / g;
  const base = normalizedMod(s * (b / g), period);
  return { base, period, count: g };
}

function chineseRemainder(equations) {
  if (!Array.isArray(equations) || equations.length === 0)
    throw new TypeError("Supply a nonempty array of congruences");
  const rows = Array.from(equations, row => {
    if (!row || typeof row.residue !== "bigint" ||
        typeof row.modulus !== "bigint")
      throw new TypeError("Each row needs BigInt residue and modulus");
    if (row.modulus <= 1n) throw new RangeError("Moduli must exceed 1");
    return { residue: row.residue, modulus: row.modulus };
  });
  const modulus = rows.reduce((product, row) => product * row.modulus, 1n);
  let sum = 0n;
  for (const row of rows) {
    const partial = modulus / row.modulus;
    const inverse = inverseMod(partial, row.modulus);
    if (inverse === null) throw new RangeError("Moduli must be pairwise coprime");
    sum += normalizedMod(row.residue, row.modulus) * partial * inverse;
  }
  return { residue: normalizedMod(sum, modulus), modulus };
}

function powerLogTable(p, r) {
  if (typeof p !== "bigint" || typeof r !== "bigint")
    throw new TypeError("Use BigInt integers");
  if (p < 2n || p > 10000n || !isPrime(p))
    throw new RangeError("Use a prime from 2 through 10000");
  const base = normalizedMod(r, p);
  if (base === 0n) throw new RangeError("Use a nonzero base modulo p");
  const logs = new Map();
  let value = 1n;
  for (let e = 0n; e < p - 1n; e++) {
    if (logs.has(value)) throw new RangeError("The base is not a primitive root");
    logs.set(value, e);
    value = (value * base) % p;
  }
  return logs;
}
